<?php declare(strict_types=1); $isEdit = $selectedAdminEvent !== null; $eventDate = $selectedAdminEvent['event_date'] ?? ''; $eventTime = isset($selectedAdminEvent['event_time']) ? substr((string) $selectedAdminEvent['event_time'], 0, 5) : ''; ?>
<section class="view hidden" id="view-admin-event-form" data-title="<?= $isEdit ? 'Edit event' : 'Create event' ?>" data-section="Administration"><button class="back-link" data-view="admin-events">← Back to events</button><div class="form-heading"><div><span class="eyebrow gold-eyebrow"><?= $isEdit ? 'EDIT EVENT' : 'NEW EVENT' ?></span><h1><?= $isEdit ? 'Edit an event' : 'Create an event' ?></h1><p class="muted"><?= $isEdit ? 'Update this opportunity in the campus calendar.' : 'Publish an opportunity your community can show up for.' ?></p></div><div class="live-preview"><span>LIVE PREVIEW</span><strong id="event-preview-title"><?= e($selectedAdminEvent['title'] ?? 'Your event title') ?></strong><small id="event-preview-date"><?= e($eventDate ?: 'Choose a date') ?> · <?= e($eventTime ?: 'Choose a time') ?></small></div></div>
<form class="panel admin-form validate-form" data-server-form="true" method="post" action="index.php?action=<?= $isEdit ? 'update-event' : 'create-event' ?>"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><?php if ($isEdit): ?><input type="hidden" name="id" value="<?= (int) $selectedAdminEvent['event_id'] ?>"><?php endif; ?><div class="form-section"><h2>Event details</h2><div class="form-grid"><div class="field-span"><label for="event-club">Hosting club</label><select id="event-club" name="club_id" required><option value="">Select a club</option><?php foreach ($clubs as $club): ?><option value="<?= (int) $club['club_id'] ?>" <?= (int) ($selectedAdminEvent['club_id'] ?? 0) === (int) $club['club_id'] ? 'selected' : '' ?>><?= e($club['name']) ?></option><?php endforeach; ?></select></div><div class="field-span"><label for="event-title">Event title</label><input id="event-title" name="title" type="text" value="<?= e($selectedAdminEvent['title'] ?? '') ?>" maxlength="150" required></div><div><label for="event-date">Date</label><input id="event-date" name="event_date" type="date" value="<?= e($eventDate) ?>" required></div><div><label for="event-time">Start time</label><input id="event-time" name="event_time" type="time" value="<?= e($eventTime) ?>" required></div><div><label for="event-location">Location</label><input id="event-location" name="venue" type="text" value="<?= e($selectedAdminEvent['venue'] ?? '') ?>" maxlength="150" required></div><div><label for="event-capacity">Capacity</label><input id="event-capacity" name="capacity" type="number" min="1" value="<?= e($selectedAdminEvent['capacity'] ?? '') ?>" required></div><div class="field-span"><label for="event-description">Description</label><textarea id="event-description" name="description" rows="4" maxlength="5000" required><?= e($selectedAdminEvent['description'] ?? '') ?></textarea></div></div></div><div class="form-actions"><button class="button button-outline" type="button" data-view="admin-events">Cancel</button><button class="button button-dark" type="submit"><?= $isEdit ? 'Update event' : 'Publish event' ?> <span>→</span></button></div></form>
</section>
